// Every request must get an answer. An uncaught throw here would leave the
// webhook hanging and look to the caller like a dead endpoint, so the whole
// handler is wrapped: anything unexpected becomes a readable 500 instead.
//
// ONE OUTPUT, TWO BRANCHES
//   A Code node has a single output, so it cannot return one item per branch.
//   It returns ONE item carrying both halves of the reply:
//     .status / .body   the API reply "Respond with CORS" sends to the browser
//     .notify           present only when an email was queued
//   Both "Respond with CORS" and the "Email queued?" gate hang off that one
//   output. The gate skips the mail branch when .notify is absent, so a mail
//   failure can never delay or break a booking request the studio is waiting on.

try {
  // ------------------------------------------------------------------ STUDIO
  // Deployment values. The SMTP login is NOT here: it lives in an n8n credential
  // attached to the two "Email:" nodes, so no password ever sits in this file.
  const STUDIO = {
    name: 'Inkheaven',
    fromName: 'Rounak',
    fromEmail: 'kumarrounak.dev@gmail.com',
    // Shown in the email footer.
    city: 'Delhi',
    // Where a customer lands to answer a reschedule offer.
    bookingUrl: 'http://localhost:5173/#booking',
    // How many alternative slots a reschedule email offers.
    offerCount: 3,
    // Opening hours: Mon-Sat, 11:00-18:00. Mirrors the website booking form.
    weekdays: [1, 2, 3, 4, 5, 6],
    hours: ['11:00', '12:00', '13:00', '14:00', '15:00', '16:00', '17:00', '18:00'],
  };

  // Every email kind this workflow can queue. Each one carries a `kind` on the
  // `notify` payload, and the "Which email?" node routes on it, so adding a kind
  // means: add it here, set kind on the builder, and add a branch.
  const EMAIL_KINDS = ['confirmation', 'reschedule', 'unavailable'];

  // Single entry point for both apps. One URL, routed on whether the body
  // carries an `action`:
  //
  //   no action  -> a booking submitted from the Inkheaven website form
  //   action     -> an Inkdesk request (list, dashboard, reschedule, ...)
  //
  // Storage is the workflow's own static data, so there is no database and no
  // credential to configure. See README.md for the trade-off and the
  // file-backed alternative.

  const incoming = $input.first().json ?? {};
  const raw = incoming.body ?? incoming;

  // inkdesk sends text/plain to dodge a CORS preflight, so n8n hands the body
  // over as a string rather than a parsed object.
  let body = raw;
  if (typeof raw === 'string') {
    const text = raw.trim();
    if (text) {
      try {
        body = JSON.parse(text);
      } catch {
        return [{ json: { status: 400, body: { ok: false, error: 'bad_request', message: 'Body was not valid JSON.' } } }];
      }
    } else {
      body = {};
    }
  }
  if (!body || typeof body !== 'object' || Array.isArray(body)) body = {};

  // ------------------------------------------------------------------ helpers

  const pad = (n) => String(n).padStart(2, '0');

  const dayISO = (offset = 0) => {
    const d = new Date();
    d.setDate(d.getDate() + offset);
    return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
  };

  const stampNow = () => {
    const d = new Date();
    return `${dayISO(0)}T${pad(d.getHours())}:${pad(d.getMinutes())}:00`;
  };

  // Inkheaven sends date as dd-mm-yyyy; Inkdesk compares against yyyy-mm-dd.
  const toISODate = (v) => {
    const s = String(v == null ? '' : v).trim();
    if (/^\d{4}-\d{2}-\d{2}$/.test(s)) return s;
    const m = /^(\d{2})-(\d{2})-(\d{4})$/.exec(s);
    return m ? `${m[3]}-${m[2]}-${m[1]}` : null;
  };

  const str = (v, max = 2000) =>
    String(v == null ? '' : v).replace(/[\u0000-\u001f\u007f]/g, ' ').trim().slice(0, max);

  // A real clock time. A bare \d{2}:\d{2} test would happily accept 99:99.
  const toTime = (v) => {
    const m = /^(\d{2}):(\d{2})$/.exec(str(v, 5));
    if (!m) return null;
    const hours = Number(m[1]);
    const minutes = Number(m[2]);
    if (hours > 23 || minutes > 59) return null;
    return `${pad(hours)}:${pad(minutes)}`;
  };

  const clone = (v) => JSON.parse(JSON.stringify(v));

  const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  const ALL_STATUSES = ['new', 'confirmed', 'rescheduled', 'completed', 'cancelled'];
  const ACTIVE_STATUSES = ['new', 'confirmed', 'rescheduled'];

  // Dates rendered by hand rather than via toLocaleString: the n8n container's
  // locale must not decide what month a customer reads.
  const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
  const WEEKDAYS = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];

  const parseISODate = (iso) => {
    const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(String(iso || ''));
    return m ? new Date(Number(m[1]), Number(m[2]) - 1, Number(m[3])) : null;
  };

  const shortDate = (iso) => {
    const d = parseISODate(iso);
    return d ? `${WEEKDAYS[d.getDay()]} ${d.getDate()} ${MONTHS[d.getMonth()]}` : String(iso || '');
  };

  const longDate = (iso) => {
    const d = parseISODate(iso);
    return d ? `${WEEKDAYS[d.getDay()]}, ${d.getDate()} ${MONTHS[d.getMonth()]} ${d.getFullYear()}` : String(iso || '');
  };

  const prettyTime = (t) => {
    const m = /^(\d{2}):(\d{2})$/.exec(String(t || ''));
    if (!m) return String(t || '');
    const h = Number(m[1]);
    return `${h % 12 || 12}:${m[2]} ${h >= 12 ? 'PM' : 'AM'}`;
  };

  const firstName = (v) => String(v || '').trim().split(/\s+/)[0] || 'there';

  // ------------------------------------------------------------------- store

  const store = $getWorkflowStaticData('global');
  if (!store.appointments) store.appointments = {};
  if (!store.blockedDates) store.blockedDates = [];
  if (!store.seq) store.seq = 1;

  const data = store.appointments;
  const blockedDates = store.blockedDates;

  const all = () => Object.values(data);
  const bySessionAsc = (a, b) => (a.date === b.date ? (a.time < b.time ? -1 : 1) : a.date < b.date ? -1 : 1);

  const applyScope = (items, scope) => {
    const today = dayISO(0);
    const out = items.slice();
    if (scope === 'upcoming') {
      return out.filter((a) => ACTIVE_STATUSES.includes(a.status) && a.date >= today).sort(bySessionAsc);
    }
    if (scope === 'today') {
      return out.filter((a) => a.date === today && a.status !== 'cancelled').sort(bySessionAsc);
    }
    if (scope === 'past') {
      return out
        .filter((a) => a.date < today || ['completed', 'cancelled'].includes(a.status))
        .sort((a, b) => bySessionAsc(b, a));
    }
    return out.sort((a, b) => bySessionAsc(b, a));
  };

  // ------------------------------------------------------------- reply shape
  // Exactly one item out, whatever happens. `notify` rides along on that item and is
  // simply absent when there is nothing to send, so the "Email queued?" gate can
  // skip the mail branch without a second Code output existing.
  //
  // This MUST stay a flat array of items. A Code node has one output, so there is
  // nowhere for a second item to go: returning `[[{...}]]` makes n8n read the inner
  // array as an item and fail with "Code doesn't return items properly". The
  // original bug was returning a *second* item here at all -- one item carrying
  // both halves is the whole fix.
  const build = (status, payload, notify) => [
    { json: { status, body: payload, ...(notify ? { notify } : {}) } },
  ];

  const ok = (data, notify) => build(200, { ok: true, data }, notify);
  const fail = (error, message, fields) =>
    build(error === 'notfound' ? 404 : error === 'auth' ? 401 : 400, { ok: false, error, message, ...(fields ? { fields } : {}) });

  const nextId = () => {
    const id = 'APT-' + String(store.seq).padStart(4, '0');
    store.seq += 1;
    return id;
  };

  // ------------------------------------------------------------ slot finding
  // The next open slots, one per day so the customer gets real choices instead
  // of three consecutive hours on a single date. Skips closed days, days the
  // studio blocked, and times an active appointment already holds. `exceptId`
  // lets a customer answer an offer with the slot they already hold.
  const slotTaken = (date, time, exceptId) =>
    all().some((a) => a.id !== exceptId && a.date === date && a.time === time && ACTIVE_STATUSES.includes(a.status));

  const dayBlocked = (date) => blockedDates.some((b) => b.date === date);

  // Why a requested slot cannot be honoured, or null when it is fine. One
  // definition shared by every path that accepts a date, so the website form
  // and an emailed offer can never disagree about what is bookable.
  //
  // `exceptId` keeps a customer from colliding with the booking they are
  // already updating: answering an offer with the slot they already hold is
  // not a clash. `hoursLabel` is the email-footer helper, called here only at
  // run time so the message quotes exactly the hours the studio is open.
  const DAYS_FULL = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];

  const slotProblem = (date, time, exceptId) => {
    const d = parseISODate(date);
    if (!d) return 'We could not read that date.';
    if (date < dayISO(0)) return 'That date has already passed.';
    if (!STUDIO.weekdays.includes(d.getDay())) return `The studio is closed on ${DAYS_FULL[d.getDay()]}s.`;
    if (dayBlocked(date)) return `The studio has blocked ${longDate(date)}.`;
    if (!STUDIO.hours.includes(time)) return `We are only open ${hoursLabel()}.`;
    if (slotTaken(date, time, exceptId)) return `${longDate(date)} at ${prettyTime(time)} is already booked.`;
    return null;
  };

  function nextFreeSlots(count, from) {
    const out = [];
    const cursor = new Date();
    cursor.setHours(0, 0, 0, 0);
    // Tomorrow is the floor: an old request must not produce slots in the past.
    cursor.setDate(cursor.getDate() + 1);
    // But never offer anything before the date the customer already asked for.
    const floor = parseISODate(toISODate(from));
    if (floor && floor.getTime() > cursor.getTime()) cursor.setTime(floor.getTime());

    for (let guard = 0; out.length < count && guard < 180; guard += 1) {
      const iso = `${cursor.getFullYear()}-${pad(cursor.getMonth() + 1)}-${pad(cursor.getDate())}`;
      if (STUDIO.weekdays.includes(cursor.getDay()) && !dayBlocked(iso)) {
        for (const time of STUDIO.hours) {
          if (slotTaken(iso, time)) continue;
          out.push({ date: iso, time });
          break;
        }
      }
      cursor.setDate(cursor.getDate() + 1);
    }
    return out;
  }

  // Slots the admin picked by hand. Junk entries are dropped rather than
  // rejecting the whole request, so one bad row cannot cost the whole offer.
  const normalizeOptions = (list) => {
    const out = [];
    const seen = new Set();
    for (const raw of Array.isArray(list) ? list : []) {
      const item = raw && typeof raw === 'object' ? raw : {};
      const date = toISODate(item.date);
      const time = toTime(item.time);
      if (!date || !time) continue;
      const key = `${date} ${time}`;
      if (seen.has(key)) continue;
      seen.add(key);
      out.push({ date, time });
      if (out.length >= STUDIO.offerCount) break;
    }
    return out;
  };

  // ------------------------------------------------------------------ emails
  // Every interpolated value is escaped. `name`, `description` and the reschedule
  // `note` are supplied by whoever filled in the website form, and this is the
  // first place attacker-controlled text lands inside HTML.
  const esc = (v) =>
    String(v == null ? '' : v)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#39;');

  // Palette. The ink and steel-blue values are lifted from the site theme, so a
  // confirmation looks like it came from Inkheaven rather than from a mail
  // library. `accent` is the darkened steel blue: the bright one is too light to
  // carry text or a button on white.
  const T = {
    page: '#e8e6e2',
    card: '#ffffff',
    ink: '#0b0e11',
    text: '#14171a',
    body: '#3d4550',
    muted: '#6b7480',
    line: '#e5e2dd',
    tint: '#f4f6f8',
    accent: '#45617a',
    accentLt: '#8fa8c0',
    quote: '#faf9f7',
  };

  // Bodoni Moda is a webfont and will never load in a mail client, so the display
  // role falls back to Georgia, which carries a similar editorial weight.
  //
  // Every style below writes font properties longhand (`font-family`,
  // `font-size`, `font-weight`, `line-height`) instead of the `font:` shorthand.
  // Outlook's Word engine ignores the shorthand, which would otherwise render the
  // entire email in default Times New Roman at the wrong size.
  const SERIF = "Georgia,'Times New Roman',Times,serif";
  const SANS = "-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif";

  // Hidden inbox preview line. Without it, clients show the first *visible* words
  // as the preview, which is usually just the greeting.
  const preheader = (text) =>
    `<div style="display:none;max-height:0;overflow:hidden;mso-hide:all;font-size:1px;line-height:1px;color:${T.page};opacity:0;">${esc(text)}</div>`;

  const button = (href, label) =>
    `<table role="presentation" cellpadding="0" cellspacing="0" style="margin:0;"><tr>
<td bgcolor="${T.ink}" align="center" style="background:${T.ink};border-radius:999px;">
<a href="${esc(href)}" style="display:inline-block;padding:15px 32px;font-family:${SANS};font-size:15px;font-weight:700;line-height:1;letter-spacing:.01em;color:#ffffff;text-decoration:none;border-radius:999px;">${esc(label)}</a>
</td></tr></table>`;

  // Aggressive clients strip the button and leave nothing behind, so the link is
  // always repeated as plain text underneath it.
  const fallbackLink = (href) =>
    `<p style="margin:12px 0 0;font-family:${SANS};font-size:12px;line-height:1.6;color:${T.muted};">Or paste this link into your browser:<br><a href="${esc(href)}" style="color:${T.accent};text-decoration:underline;">${esc(href)}</a></p>`;

  // Date and time get their own block: they are the first thing anyone looks for,
  // and they used to be two rows competing with the design notes for attention.
  const whenBlock = (a) =>
    `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin:0 0 22px;background:${T.tint};border:1px solid ${T.line};border-left:3px solid ${T.accent};border-radius:10px;"><tr>
<td style="padding:18px 20px;">
<p style="margin:0;font-family:${SANS};font-size:10px;font-weight:700;line-height:1;letter-spacing:.16em;text-transform:uppercase;color:${T.muted};">Date &amp; time</p>
<p class="hero" style="margin:9px 0 0;font-family:${SERIF};font-size:22px;line-height:1.25;color:${T.text};">${esc(longDate(a.date))}</p>
<p style="margin:4px 0 0;font-family:${SANS};font-size:15px;font-weight:700;line-height:1.3;color:${T.accent};">${esc(prettyTime(a.time))}</p>
</td></tr></table>`;

  // The remaining facts, demoted to a quiet hairline table. Reference first so it
  // stays easy to find when someone is looking up a booking.
  const details = (pairs) => {
    const rows = pairs.filter(Boolean);
    if (!rows.length) return '';
    return `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin:0 0 22px;">${rows
      .map(
        ([k, v]) => `<tr>
<td width="34%" valign="top" style="padding:11px 12px 11px 0;border-bottom:1px solid ${T.line};font-family:${SANS};font-size:10px;font-weight:700;line-height:1.5;letter-spacing:.12em;text-transform:uppercase;color:${T.muted};">${esc(k)}</td>
<td valign="top" style="padding:11px 0;border-bottom:1px solid ${T.line};font-family:${SANS};font-size:15px;font-weight:600;line-height:1.45;color:${T.text};">${esc(v)}</td>
</tr>`
      )
      .join('')}</table>`;
  };

  // A note from the studio, set as a pull-quote so it reads as an aside rather
  // than as body copy.
  const quote = (text) =>
    `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin:0 0 22px;background:${T.quote};border-left:3px solid ${T.accentLt};border-radius:8px;"><tr>
<td style="padding:15px 18px;font-family:${SANS};font-size:14px;font-weight:400;line-height:1.6;font-style:italic;color:${T.body};">${esc(text)}</td>
</tr></table>`;

  // Reschedule options: stacked full-width cards instead of small side-by-side
  // chips. These options are the entire point of the email, so each one gets room
  // to breathe on a phone and carries an option number, which makes the reply
  // obvious ("Option 2 works").
  const slotCard = (slot, i) =>
    `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin:0 0 10px;background:#ffffff;border:1px solid ${T.line};border-radius:10px;"><tr>
<td width="4" style="background:${T.accent};font-size:0;line-height:0;border-radius:10px 0 0 10px;">&nbsp;</td>
<td style="padding:14px 18px;">
<p style="margin:0;font-family:${SANS};font-size:10px;font-weight:700;line-height:1;letter-spacing:.14em;text-transform:uppercase;color:${T.muted};">Option ${i + 1}</p>
<p style="margin:7px 0 0;font-family:${SERIF};font-size:18px;line-height:1.25;color:${T.text};">${esc(shortDate(slot.date))}</p>
<p style="margin:3px 0 0;font-family:${SANS};font-size:14px;font-weight:700;line-height:1.3;color:${T.accent};">${esc(prettyTime(slot.time))}</p>
</td></tr></table>`;

  // Opening hours are read straight off STUDIO so the email can never drift from
  // the times the booking form actually offers.
  const hoursLabel = () => {
    const names = STUDIO.weekdays.map((d) => WEEKDAYS[d]);
    // A contiguous run renders as a range (Mon–Sat). Enumerating every day reads
    // as noise in a one-line footer.
    const contiguous =
      names.length > 2 && names.every((n, i) => i === 0 || WEEKDAYS.indexOf(names[i - 1]) + 1 === WEEKDAYS.indexOf(n));
    const days = contiguous ? `${names[0]}–${names[names.length - 1]}` : names.join(', ');
    const first = prettyTime(STUDIO.hours[0]);
    const last = prettyTime(STUDIO.hours[STUDIO.hours.length - 1]);
    return `${days} · ${first} – ${last}`;
  };

  const shell = ({ eyebrow, heading, prehead }, inner) => `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<meta name="color-scheme" content="light">
<meta name="supported-color-schemes" content="light">
<title>${esc(STUDIO.name)}</title>
<style>
@media only screen and (max-width:560px){
  .outer{padding:16px 10px !important}
  .pad{padding-left:20px !important;padding-right:20px !important}
  .h1{font-size:22px !important}
  .hero{font-size:19px !important}
}
</style>
</head>
<body style="margin:0;padding:0;background:${T.page};-webkit-text-size-adjust:100%;-ms-text-size-adjust:100%;">
${preheader(prehead)}
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" class="outer" style="background:${T.page};padding:32px 14px;">
<tr><td align="center" style="padding:0;">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:580px;background:${T.card};border:1px solid ${T.line};border-radius:16px;">
<tr><td class="pad" style="padding:28px 32px 26px;background:${T.ink};border-radius:15px 15px 0 0;">
<p style="margin:0;font-family:${SANS};font-size:10px;font-weight:700;line-height:1;letter-spacing:.26em;text-transform:uppercase;color:${T.accentLt};">${esc(STUDIO.name)}</p>
<p style="margin:12px 0 0;font-family:${SANS};font-size:11px;font-weight:600;line-height:1.4;letter-spacing:.08em;color:#8b929b;">${esc(eyebrow)}</p>
</td></tr>
<tr><td height="3" style="height:3px;font-size:0;line-height:0;background:${T.accentLt};">&nbsp;</td></tr>
<tr><td class="pad" style="padding:30px 32px 32px;font-family:${SANS};font-size:15px;line-height:1.65;color:${T.body};">
<h1 class="h1" style="margin:0 0 18px;font-family:${SERIF};font-size:26px;font-weight:400;line-height:1.25;color:${T.text};">${esc(heading)}</h1>
${inner}
</td></tr>
<tr><td class="pad" style="padding:20px 32px;background:${T.quote};border-top:1px solid ${T.line};border-radius:0 0 15px 15px;font-family:${SANS};font-size:12px;line-height:1.7;color:${T.muted};">
<p style="margin:0 0 6px;font-family:${SANS};font-size:10px;font-weight:700;line-height:1.4;letter-spacing:.12em;text-transform:uppercase;color:${T.text};">${esc(STUDIO.name)}</p>
<p style="margin:0;">${esc(STUDIO.city)} · ${esc(hoursLabel())}<br>Reply to this email to reach ${esc(STUDIO.fromName)} at the studio.</p>
</td></tr>
</table>
</td></tr></table>
</body></html>`;

  const confirmationEmail = (a) => ({
    // `kind` is what lets n8n route the two emails apart: the IF node splits on
    // it, and it shows up in the execution log so a send is identifiable after
    // the fact. Keep these values stable — the node expressions match on them.
    kind: 'confirmation',
    to: a.email,
    toName: a.name,
    appointmentId: a.id,
    subject: `Your ${STUDIO.name} booking is confirmed — ${a.id}`,
    html: shell(
      {
        eyebrow: 'Appointment confirmed',
        heading: `Confirmed, ${firstName(a.name)}`,
        prehead: `Locked in for ${longDate(a.date)} at ${prettyTime(a.time)} — reference ${a.id}.`,
      },
      `<p style="margin:0 0 18px;">Your session is locked in. Everything you need is below:</p>
${whenBlock(a)}
${details([
  ['Reference', a.id],
  ['Style', a.style],
  ['Placement', a.placement],
  ['Size', a.size],
])}
<p style="margin:0;font-family:${SANS};font-size:13px;line-height:1.65;color:${T.muted};">Plans change — just reply to this email and we will send you a few alternative times.</p>`
    ),
  });

  const rescheduleEmail = (a, slots, note) => ({
    kind: 'reschedule',
    to: a.email,
    toName: a.name,
    appointmentId: a.id,
    subject: `Let's find a better time for your tattoo — ${a.id}`,
    html: shell(
      {
        eyebrow: 'Action needed',
        heading: 'We need to move your session',
        prehead: `Your request ${a.id} is still open — ${
          slots.length
            ? `pick one of ${slots.length} new times.`
            : 'tell us what suits you.'
        }`,
      },
      `<p style="margin:0 0 16px;">Hi ${esc(firstName(a.name))},</p>
<p style="margin:0 0 20px;">Sorry — <strong style="color:${T.text};font-weight:700;">${esc(
        longDate(a.date)
      )} at ${esc(prettyTime(a.time))}</strong> no longer works for us. Nothing is lost: your request <span style="color:${
        T.text
      };font-weight:600;">${esc(a.id)}</span> is still open.</p>
${note ? quote(note) : ''}
${
  slots.length
    ? `<p style="margin:0 0 12px;font-family:${SANS};font-size:14px;font-weight:700;line-height:1.5;color:${
        T.text
      };">These slots are open — reply with the number you want, or pick one yourself:</p>
${slots.map(slotCard).join('')}`
    : `<p style="margin:0 0 20px;">Tell us what suits you and we will work around it.</p>`
}
${button(STUDIO.bookingUrl, 'Pick a time on the website')}
${fallbackLink(STUDIO.bookingUrl)}`
    ),
  });

  // Sent when a customer asks for a slot the studio cannot honour: a Sunday,
  // a blocked date, a time outside opening hours, or one already booked.
  // Reuses the "pick another time" node, so it needs no new SMTP credential.
  const unavailableEmail = (a, reason, slots) => ({
    kind: 'unavailable',
    to: a.email,
    toName: a.name,
    appointmentId: a.id,
    subject: `Let’s find a time that works — ${a.id}`,
    html: shell(
      {
        eyebrow: 'Slot unavailable',
        heading: `${firstName(a.name)}, we need a different time`,
        prehead: `${reason} ${
          slots.length
            ? `Here are ${slots.length} other times that are open.`
            : 'Tell us roughly when suits you and we will work around it.'
        }`,
      },
      `<p style="margin:0 0 16px;">Hi ${esc(firstName(a.name))},</p>
<p style="margin:0 0 20px;">Thanks for reaching out about your ${esc(a.style || 'tattoo')}${
        a.placement ? ` for your ${esc(a.placement)}` : ''
      }. You asked for <strong style="color:${T.text};font-weight:700;">${esc(longDate(a.date))} at ${esc(
        prettyTime(a.time)
      )}</strong>.</p>
${quote(reason)}
${
  slots.length
    ? `<p style="margin:0 0 12px;font-family:${SANS};font-size:14px;font-weight:700;line-height:1.5;color:${T.text};">These times are open — reply with the number you want, or pick one yourself:</p>
      ${slots.map(slotCard).join('')}`
    : `<p style="margin:0 0 20px;">Our calendar is filling up. Tell us roughly when suits you and we will work around it.</p>`
}
<p style="margin:0 0 20px;font-family:${SANS};font-size:13px;line-height:1.65;color:${T.muted};">Your details are with the studio either way, so nothing has been lost.</p>
${button(STUDIO.bookingUrl, 'Pick a time on the website')}
${fallbackLink(STUDIO.bookingUrl)}`
    ),
  });

  // Queues an email only when there is a usable address. Manual bookings are
  // often added without one, and silently skipping is better than bouncing.
  const notifyFor = (build_, a, ...rest) =>
    EMAIL_RE.test(String(a.email || '')) ? build_(a, ...rest) : null;

  // A slot the studio cannot honour. The request is never dropped: it stays
  // stored and flagged so the studio still sees the enquiry, while the
  // customer is told what to do next and handed real alternatives rather than
  // a dead end. `wanted` is the slot they asked for, which is not always the
  // slot on the record - answering an offer leaves the old date in place, so
  // only the response reports `wanted`; the record keeps its own date and is
  // flagged in place.
  // Records why a requested slot could not be honoured, on the stored record
  // so it survives to `list` and the dashboard. It also leaves an admin note:
  // the dashboard shows the date, not why that date is a problem, and this is
  // the only place that reasoning is captured. Each refusal is a separate
  // enquiry, so re-submitting appends rather than overwrites.
  const noteIssue = (a, reason, slots) => {
    a.slot_request_issue = reason;
    a.suggested_slots = slots;
    a.updated_at = stampNow();
    a.admin_notes = `${a.admin_notes ? `${a.admin_notes}\n\n` : ''}Requested slot unavailable: ${reason} (asked for ${longDate(a.date)} at ${prettyTime(a.time)}).`;
  };

  const unavailableReply = (a, wanted, reason) => {
    const slots = nextFreeSlots(STUDIO.offerCount, wanted.date);
    const notify = notifyFor(unavailableEmail, { ...a, date: wanted.date, time: wanted.time }, reason, slots);
    noteIssue(a, reason, slots);
    const out = clone(a);
    out.emailQueued = Boolean(notify);
    out.emailKind = notify ? notify.kind : null;
    return ok(out, notify);
  };

  // ------------------------------------------------- intake: website booking

  // No `action` means the Inkheaven booking form. The proxy already sanitised
  // this, but the workflow can also be hit directly, so re-check.
  if (!body.action) {
    // Honeypot: a bot filled it in. Report success, store nothing.
    if (body.company) return ok({ received: true });

    const fields = {};
    const name = str(body.name, 120);
    const email = str(body.email, 200);
    const phone = str(body.phone, 40);
    const description = str(body.description, 4000);

    if (!name) fields.name = 'Name is required.';
    if (!email) fields.email = 'Email is required.';
    else if (!EMAIL_RE.test(email)) fields.email = 'Enter a valid email address.';
    if (!phone) fields.phone = 'Phone is required.';
    if (!description) fields.description = 'Tell us about the tattoo.';
    if (Object.keys(fields).length) return fail('validation', 'Please check the highlighted fields.', fields);

    const now = stampNow();

    // A customer answering a reschedule offer comes back through the same form,
    // with no reference to the booking they are replying to. Matching on the
    // contact details closes the loop: their answer updates the open request
    // instead of piling up as an unrelated new one.
    const openOffer = all().find(
      (a) =>
        a.awaiting_customer === true &&
        ((a.email && String(a.email).toLowerCase() === email.toLowerCase()) || (a.phone && a.phone === phone))
    );

    if (openOffer) {
      const wanted = {
        date: toISODate(body.dateIso) || toISODate(body.date) || openOffer.date,
        time: toTime(body.time) || openOffer.time,
      };
      // The form lets a customer type any date, not just the ones on the
      // offer. If the slot they picked is one the studio cannot honour, leave
      // the offer open and send real alternatives rather than booking a
      // Sunday. The clinic already holding this slot is excluded, so
      // re-picking the date they already have is not treated as a clash.
      const clash = slotProblem(wanted.date, wanted.time, openOffer.id);
      if (clash) return unavailableReply(openOffer, wanted, clash);

      openOffer.date = wanted.date;
      openOffer.time = wanted.time;
      openOffer.status = 'confirmed';
      openOffer.awaiting_customer = false;
      openOffer.proposed_slots = [];
      openOffer.rescheduled_via = 'website';
      // The offer is being answered, so an earlier "that slot is unavailable"
      // flag is history: keeping it would read as a live problem on a booking
      // that is now confirmed. The admin note keeps the trail.
      if (openOffer.slot_request_issue) {
        delete openOffer.slot_request_issue;
        delete openOffer.suggested_slots;
      }
      openOffer.updated_at = now;
      openOffer.admin_notes = `${openOffer.admin_notes ? `${openOffer.admin_notes}\n\n` : ''}Customer picked a new slot via the website form on ${now}.`;
      return ok(clone(openOffer));
    }

    const record = {
      id: nextId(),
      created_at: now,
      name,
      email: email.toLowerCase(),
      phone,
      style: str(body.style, 40) || 'other',
      placement: str(body.placement, 40),
      size: str(body.size, 40),
      description,
      date: toISODate(body.dateIso) || toISODate(body.date) || dayISO(0),
      time: toTime(body.time) || '12:00',
      budget: str(body.budget, 40),
      status: 'new',
      admin_notes: '',
      updated_at: now,
      source: 'website',
      awaiting_customer: false,
      proposed_slots: [],
    };

    // Computed BEFORE the record is stored: once it exists, slotTaken() would
    // find this very booking and report every request as a clash.
    const issue = slotProblem(record.date, record.time);

    data[record.id] = record;
    if (issue) return unavailableReply(record, { date: record.date, time: record.time }, issue);
    return ok(clone(record));
  }

  // ------------------------------------------------------------ inkdesk: api

  const action = String(body.action || '').trim();
  const params = body.params && typeof body.params === 'object' ? body.params : {};

  switch (action) {
    // Settings > Test connection.
    case 'ping':
      return ok({ service: 'inkdesk-api (n8n)', version: 1 });

    case 'list': {
      let items = all();
      const status = String(params.status || 'all');
      const q = String(params.q || '').trim().toLowerCase();

      if (status !== 'all') items = items.filter((a) => a.status === status);
      if (q) {
        items = items.filter((a) =>
          `${a.name} ${a.email} ${a.phone} ${a.id}`.toLowerCase().includes(q),
        );
      }
      return ok({ items: applyScope(items, String(params.scope || 'upcoming')) });
    }

    case 'clientHistory': {
      const q = String(params.q || '').trim().toLowerCase();
      if (!q) return fail('validation', 'A phone or email is required.');

      const matches = all().filter(
        (a) => String(a.phone).toLowerCase() === q || String(a.email).toLowerCase() === q,
      );
      matches.sort((a, b) => bySessionAsc(b, a));

      const first = matches[0] || null;
      return ok({
        items: clone(matches),
        count: matches.length,
        client: first ? { name: first.name, phone: first.phone, email: first.email } : null,
      });
    }

    case 'dashboard': {
      const today = dayISO(0);
      const items = all();
      const counts = { all: items.length, new: 0, confirmed: 0, rescheduled: 0, completed: 0, cancelled: 0 };

      items.forEach((a) => {
        if (counts[a.status] != null) counts[a.status] += 1;
      });

      const upcomingItems = items
        .filter((a) => ACTIVE_STATUSES.includes(a.status) && a.date >= today)
        .sort(bySessionAsc);
      const weekEnd = dayISO(6);

      return ok({
        counts,
        today: items.filter((a) => a.date === today && !['cancelled', 'completed'].includes(a.status)).length,
        week: upcomingItems.filter((a) => a.date <= weekEnd).length,
        upcoming: upcomingItems.length,
      });
    }

    case 'meta':
      return ok({ blockedDates: clone(blockedDates) });

    // Feeds the reschedule modal so the admin can see — and trim — exactly what
    // the customer will be offered before anything is sent. `from` is the
    // appointment's current date, so the preview matches what will be sent.
    case 'suggestSlots': {
      const asked = Number(params.count);
      const count = Number.isFinite(asked) && asked > 0 ? Math.min(8, Math.floor(asked)) : STUDIO.offerCount;
      return ok({ items: nextFreeSlots(count, params.from) });
    }

    case 'updateStatus': {
      const appointment = data[String(body.id || '')];
      if (!appointment) return fail('notfound', 'Appointment not found.');

      const status = String(body.status || '').toLowerCase();
      if (!ALL_STATUSES.includes(status)) return fail('validation', 'Unknown status.');

      appointment.status = status;
      appointment.updated_at = stampNow();
      // Settling the booking settles any open offer with it.
      appointment.awaiting_customer = false;
      appointment.proposed_slots = [];

      // Confirmation email goes out when the studio confirms, not when the
      // request merely arrives — the studio may never confirm a spam enquiry.
      const notify = status === 'confirmed' ? notifyFor(confirmationEmail, appointment) : null;
      const out = clone(appointment);
      out.emailQueued = Boolean(notify);
      // Tells the admin which email was queued, not merely that one was.
      out.emailKind = notify ? notify.kind : null;
      return ok(out, notify);
    }

    case 'reschedule': {
      const appointment = data[String(body.id || '')];
      if (!appointment) return fail('notfound', 'Appointment not found.');

      const payload = body.payload && typeof body.payload === 'object' ? body.payload : {};
      const note = str(payload.note != null ? payload.note : payload.message, 600);
      const isOffer = Array.isArray(payload.options);

      // Immediate move: an explicit date+time without an options list. Kept so
      // the old single-slot call still behaves the way it always has.
      const moveDate = toISODate(payload.date);
      const moveTime = toTime(payload.time);
      if (!isOffer && moveDate && moveTime) {
        appointment.date = moveDate;
        appointment.time = moveTime;
        appointment.status = 'rescheduled';
        appointment.awaiting_customer = false;
        appointment.proposed_slots = [];
        appointment.updated_at = stampNow();
        const out = clone(appointment);
        out.emailQueued = false;
        out.emailKind = null;
        return ok(out);
      }

      // Offer path: propose times and let the customer choose. The original slot
      // is deliberately left in place — nothing is booked until they answer, so
      // freeing that date now would leave a hole in the calendar.
      const slots = isOffer ? normalizeOptions(payload.options) : nextFreeSlots(STUDIO.offerCount, appointment.date);

      appointment.proposed_slots = slots;
      appointment.reschedule_note = note;
      appointment.awaiting_customer = slots.length > 0;
      appointment.rescheduled_via = 'offer';
      appointment.updated_at = stampNow();

      const notify = notifyFor(rescheduleEmail, appointment, slots, note);
      const out = clone(appointment);
      out.emailQueued = Boolean(notify);
      out.emailKind = notify ? notify.kind : null;
      return ok(out, notify);
    }

    case 'saveNotes': {
      const appointment = data[String(body.id || '')];
      if (!appointment) return fail('notfound', 'Appointment not found.');

      appointment.admin_notes = str(body.notes, 2000);
      appointment.updated_at = stampNow();
      return ok(clone(appointment));
    }

    case 'addManual': {
      const payload = body.payload && typeof body.payload === 'object' ? body.payload : {};

      const fields = {};
      const name = str(payload.name, 120);
      const email = str(payload.email, 200);
      const phone = str(payload.phone, 40);
      if (!name) fields.name = 'Name is required.';
      if (!email) fields.email = 'Email is required.';
      if (!phone) fields.phone = 'Phone is required.';
      if (Object.keys(fields).length) return fail('validation', 'Please check the highlighted fields.', fields);

      const now = stampNow();
      const appointment = {
        id: nextId(),
        created_at: now,
        name,
        email: email.toLowerCase(),
        phone,
        style: str(payload.style, 40) || 'other',
        placement: str(payload.placement, 40),
        size: str(payload.size, 40),
        description: str(payload.description, 4000),
        date: toISODate(payload.date) || dayISO(0),
        time: toTime(payload.time) || '12:00',
        budget: str(payload.budget, 40),
        status: 'confirmed',
        admin_notes: '',
        updated_at: now,
        source: 'manual',
        awaiting_customer: false,
        proposed_slots: [],
      };

      data[appointment.id] = appointment;
      return ok(clone(appointment));
    }

    case 'deleteAppointment': {
      const id = String(body.id || '');
      if (!data[id]) return fail('notfound', 'Appointment not found.');
      delete data[id];
      return ok({ id });
    }

    case 'blockDate': {
      const payload = body.payload && typeof body.payload === 'object' ? body.payload : {};
      const date = toISODate(payload.date);
      if (!date) return fail('validation', 'A valid date is required.');

      const existing = blockedDates.find((b) => b.date === date);
      if (existing) existing.reason = str(payload.reason, 200);
      else blockedDates.push({ date, reason: str(payload.reason, 200) });

      return ok({ date });
    }

    case 'unblockDate': {
      const payload = body.payload && typeof body.payload === 'object' ? body.payload : {};
      const date = toISODate(payload.date);
      const index = blockedDates.findIndex((b) => b.date === date);
      if (index !== -1) blockedDates.splice(index, 1);
      return ok({ date });
    }

    default:
      return fail('bad_request', 'Unknown action: ' + action);
  }

} catch (err) {
    // Same shape every other exit uses: one item, no `notify`, so the mail
    // branch is skipped.
    return [
      {
        json: {
          status: 500,
          body: {
            ok: false,
            error: 'server',
            message: 'Could not process the request.',
          },
        },
      },
    ];
  }
